-- GenDB engine variant Q04-conjunct_permutation: template q04.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  o_orderpriority,
  COUNT(*) AS order_count
FROM orders
WHERE
  EXISTS(
    SELECT
      *
    FROM lineitem
    WHERE
      l_commitdate < l_receiptdate AND l_orderkey = o_orderkey
  )
  AND o_orderdate < $1 + INTERVAL '3 MONTH'
  AND o_orderdate >= $1
GROUP BY
  o_orderpriority
ORDER BY
  o_orderpriority
